// The process entry point retains its standard char** argv signature.
// NOLINTNEXTLINE(misc-const-correctness)
int main(int argc, char** argv) {
    // Check command line arguments.
    if (argc != 4) {
        std::cerr << "Usage: websocket-server-stackless <address> <port> <threads>\n"
                  << "Example:\n"
                  << "    websocket-server-stackless 0.0.0.0 8080 1\n";
        return EXIT_FAILURE;
    }
    auto const address = net::ip::make_address(argv[1]);
    auto const port = static_cast<unsigned short>(webcpp_fixture::integer(argv[2]));
    [[maybe_unused]] auto const threads = std::max<int>(1, webcpp_fixture::integer(argv[3]));

    // The io_context is required for all I/O
    webcpp::asio::io_context ioc{threads};

    // Create and launch a listening port
    std::make_shared<listener>(ioc, tcp::endpoint{address, port})->run();

    // Run the I/O service on the requested number of threads
    ioc.run();  // lint-run: drives the application's network operations

    return EXIT_SUCCESS;
}
